/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
for raw in ['http://localhost/%3A5','http://localhost/#%3A10','http://ex%34mple.com/p%2F12?x=%3A5#%3A10','http://localhost/a%31b2','http://localhost:8000/p%3A']:
 u=QUrl(raw)
 print(raw, '=>',bytes(u.toEncoded()).decode())
 for s in ['host','path','query','fragment']:
  f=getattr(u,s)
  try: print(s,repr(f(QUrl.FullyEncoded)),repr(f()))
  except TypeError: print(s,repr(f()))
PY"

